//! 🫴️ Original TSV receiving laws witness actual raw-grid destinations and original cancellation.
use super::*;
#[test]
fn sqlite_snapshot_tsv_receiving_original_subset_validation_uses_both_original_controls(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🛂️validation/🧫️fixtures/🔣️.json")).unwrap();let source=snapshot(&policy()["cases"][0]);let database=input(&source);let pointers=(source.schema.as_ptr(),database.tables.as_ptr());let incoming=grant(&law["grant"]);
 macro_rules! direction{
  ($native:ident,$owner:ident,$method:ident)=>{
   for case in law["cases"].as_array().unwrap(){
    let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:concat!("s.stdio.","tsv").into(),standard:"iana".into(),subset:case["subset"].as_str().unwrap().into()};let subset_pointer=dialect.subset.as_ptr();let port=case["port"].as_str().unwrap();let sql_calls=Cell::new(0usize);let native_calls=Cell::new(0usize);let mut sql_callback=|_|{sql_calls.set(sql_calls.get()+1);port!="sqlCanceled"};let mut native_callback=|_|{native_calls.set(native_calls.get()+1);port!="nativeCanceled"};let mut sql=SqliteSnapshotControl::new(&mut sql_callback,semio_framework_os_kernel::sqlite_snapshot::SqliteDatabaseLimits{max_allocation_bytes:0,..Default::default()});let mut native=$native::new(law["nativeMaximumBytes"].as_u64().unwrap()as usize,&mut native_callback);let mut owner=store::$owner::new(&mut native,incoming);
    let(result,physical)=observe(||source.$method(&dialect,&database,&mut sql,&mut owner));let(allocated,released)=(physical.requested_bytes,physical.released_bytes);
    assert_eq!((allocated,released),(law["allocatedBytes"].as_u64().unwrap()as usize,law["releasedBytes"].as_u64().unwrap()as usize));assert_eq!(owner.progress(),RetainedCloneProgress::default());assert_eq!(native_calls.get(),1);assert_eq!(sql_calls.get(),usize::from(port!="nativeCanceled"));
    match case["kind"].as_str().unwrap(){"clean"=>assert!(result.unwrap().diagnostics.is_empty()),kind=>{let error=result.unwrap_err();assert_eq!(error.cause.kind.as_str(),kind);assert!(error.diagnostics.is_empty());}}
    assert_eq!((source.schema.as_ptr(),database.tables.as_ptr()),pointers);assert_eq!(dialect.subset.as_ptr(),subset_pointer);drop(owner);assert_eq!(native.owned_bytes(),0);assert!(!native.has_retirement_owner());assert_eq!(sql.allocation_remaining_bytes(),0);
   }
  };
 }
 direction!(NativeDecodeControl,NativeSnapshotDecodeOwner,validate_sqlite_snapshot_subset_decoding);
 direction!(NativeEncodeControl,NativeSnapshotEncodeOwner,validate_sqlite_snapshot_subset_encoding);
 eprintln!("[DEBUG] TSV original subset receiving validation matches eight neutral directional cases with exact borrowed pointers, original native and SQL cancellation, zero physical allocation/release and literal unsupported policy");
}
use store::ArtifactSqliteSnapshot as _;
use semio_framework_value::{NativeDecodeControl,NativeEncodeControl,RetainedCloneGrant,RetainedCloneProgress};
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
use std::{cell::Cell,sync::atomic::{AtomicUsize,Ordering}};
fn policy()->serde_json::Value{serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap()}
fn grant(value:&serde_json::Value)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:value["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:value["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:value["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:value["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:value["maximumDepth"].as_u64().unwrap()as usize}}
fn snapshot(value:&serde_json::Value)->TsvSnapshot{TsvSnapshot{schema:value["schema"].as_str().unwrap().into(),records:value["records"].as_array().unwrap().iter().map(|row|row.as_array().unwrap().iter().map(|text|text.as_str().unwrap().into()).collect()).collect(),trailing_newline:value["trailingNewline"].as_bool().unwrap(),line_ending:match value["lineEnding"].as_str().unwrap(){"lf"=>LineEnding::Lf,"crlf"=>LineEnding::Crlf,_=>unreachable!()}}}
fn wide(law:&serde_json::Value)->TsvSnapshot{TsvSnapshot{schema:"literal-λ🙂".into(),records:vec![vec![],vec![law["stringUnit"].as_str().unwrap().repeat(law["stringRepetitions"].as_u64().unwrap()as usize),"tail".into()],vec![]],trailing_newline:true,line_ending:LineEnding::Crlf}}
fn input(source:&TsvSnapshot)->SqliteDatabase{source.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap()}
macro_rules! original{
 ($name:ident,$control:ident,$owner:ident,$module:ident,$event:ident,$allocation:ident,$recipient:ident)=>{
 fn $name<T:std::fmt::Debug>(law:&serde_json::Value,incoming:RetainedCloneGrant,sql_callback:&mut dyn FnMut(semio_framework_os_kernel::sqlite_snapshot::SqliteSnapshotProgress)->bool,native_callback:&mut dyn FnMut(semio_framework_value::$module::$event)->bool,limits:semio_framework_os_kernel::sqlite_snapshot::SqliteDatabaseLimits,operation:impl FnOnce(&mut SqliteSnapshotControl<'_>,&mut store::$owner<'_,'_>)->Result<T>)->Result<T>{
  let ledger=AtomicUsize::new(0);let mut allocate=|request:semio_framework_value::$module::$allocation|{assert_eq!(request.owned_bytes,ledger.load(Ordering::Relaxed));ledger.store(request.next_owned_bytes,Ordering::Relaxed);Ok(())};let mut recipient=semio_framework_value::$module::$recipient::new();let mut native=$control::new_forwarded(law["nativeMaximumBytes"].as_u64().unwrap()as usize,native_callback,&mut allocate);native.install_retirement_recipient(&mut recipient).unwrap();let mut control=SqliteSnapshotControl::new(sql_callback,limits);let mut owner=store::$owner::new(&mut native,incoming);
  let(result,heap)=observe(||operation(&mut control,&mut owner));let accepted=owner.progress();assert!(accepted.fits(incoming));assert_eq!(heap.requested_bytes,accepted.retained_capacity_bytes);assert_eq!(heap.released_bytes,accepted.released_bytes);if let Err(error)=&result{assert_eq!(error.retained_progress(),accepted);}drop(owner);assert_eq!(ledger.load(Ordering::Relaxed),native.owned_bytes());assert_eq!(limits.max_allocation_bytes-control.allocation_remaining_bytes(),native.owned_bytes());
  let before=native.owned_bytes();let held=native.has_retirement_owner();let(step,heap)=observe(||native.close_retirement_recipient(grant(&law["deniedCloseGrant"])).unwrap());assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(native.owned_bytes(),before);assert_eq!(native.has_retirement_owner(),held);
  if result.is_ok(){assert!(!held);return result}if accepted.retained_capacity_bytes>0&&result.as_ref().err().is_some_and(|error|matches!(error.kind,ValueRefusalKind::Canceled|ValueRefusalKind::InvalidValue)){assert!(held)}let(mut born,mut released)=(accepted.retained_capacity_bytes,accepted.released_bytes);let close=grant(&law["closeGrant"]);for _ in 0..law["maximumCloseTurns"].as_u64().unwrap(){if !native.has_retirement_owner(){assert_eq!(born,released);return result}let(step,heap)=observe(||native.close_retirement_recipient(close).unwrap());assert!(step.progress().fits(close));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;}panic!("TSV original recipient failed funded terminal")
 }
 };
}
original!(decode,NativeDecodeControl,NativeSnapshotDecodeOwner,native_decoding,NativeDecodeProgress,NativeDecodeAllocation,NativeDecodeRetirementRecipient);
original!(encode,NativeEncodeControl,NativeSnapshotEncodeOwner,native_encoding,NativeEncodeProgress,NativeEncodeAllocation,NativeEncodeRetirementRecipient);
#[test]
fn sqlite_snapshot_tsv_receiving_original_bounded_schema_interior_cancellation(){let law=policy();let source=snapshot(&law["cases"][0]);let full=grant(&law["bodyGrant"]);let scan=&law["tokenScanning"];for span in scan["spans"].as_array().unwrap(){let mut database=input(&source);let declaration=&mut database.tables[0].sql;let bytes=scan["bytes"].as_u64().unwrap()as usize;*declaration=match span.as_str().unwrap(){"whitespace"=>" ".repeat(bytes)+declaration,"identifier"=>"x".repeat(bytes),"quotedLiteral"=>"'".to_string()+&"x".repeat(bytes)+"'","escapedQuotedLiteral"=>"'".to_string()+&"''".repeat(bytes/2)+"'",_=>unreachable!()};let calls=Cell::new(0usize);let stop=scan["cancelAt"].as_u64().unwrap()as usize;let error=encode(&law,full,&mut |_|{calls.set(calls.get()+1);calls.get()<stop},&mut |_|true,Default::default(),|control,owner|TsvSnapshot::from_sqlite_database_receiving(&database,control,owner)).unwrap_err();assert_eq!(error.kind,ValueRefusalKind::Canceled);assert_eq!(calls.get(),stop);}eprintln!("[DEBUG] Original TSV borrowed authored SQL scanner cancels within98304-byte whitespace, identifier and ordinary/escaped quoted-literal interiors every256 octets without owning parsed schema backing");}
#[test]
fn sqlite_snapshot_tsv_receiving_original_neutral_raw_grid(){let law=policy();for value in law["cases"].as_array().unwrap(){let source=snapshot(value);let full=grant(&law["bodyGrant"]);let mut projected=decode(&law,full,&mut |_|true,&mut |_|true,Default::default(),|control,owner|source.to_sqlite_database_receiving(control,owner)).unwrap();let ordinary=input(&source);for table in &projected.tables{assert_eq!(table.rows,ordinary.table(&table.name).unwrap().rows);}for table in &mut projected.tables{table.rows.reverse()}let pointer=projected.tables[2].rows.as_ptr();let restored=encode(&law,full,&mut |_|true,&mut |_|true,Default::default(),|control,owner|TsvSnapshot::from_sqlite_database_receiving(&projected,control,owner)).unwrap();assert_eq!(restored,source);assert_eq!(projected.tables[2].rows.as_ptr(),pointer);assert_eq!(serde_json::Value::from(semio_framework_value::ToValue::to_value(&restored)),*value);}eprintln!("[DEBUG] Original TSV receiving preserves exact raw-grid extents, empty records, present empty fields, schema and independent newline metadata under original paid SQL/native owners, matching independent Serde semantics");}
#[test]
fn sqlite_snapshot_tsv_receiving_original_five_axes_and_zero_backing(){let law=policy();let source=wide(&law);let database=input(&source);let full=grant(&law["bodyGrant"]);for refusal in law["refusals"].as_array().unwrap(){let mut incoming=full;let value=refusal["value"].as_u64().unwrap()as usize;match refusal["axis"].as_str().unwrap(){"work"=>incoming.maximum_items=value,"copy"=>incoming.maximum_copy_bytes=value,"capacity"=>incoming.maximum_capacity_bytes=value,"release"=>incoming.maximum_release_bytes=value,"depth"=>incoming.maximum_depth=value,_=>unreachable!()}let error=decode(&law,incoming,&mut |_|true,&mut |_|true,Default::default(),|control,owner|source.to_sqlite_database_receiving(control,owner)).unwrap_err();assert_eq!(error.kind.as_str(),refusal["kind"].as_str().unwrap());let error=encode(&law,incoming,&mut |_|true,&mut |_|true,Default::default(),|control,owner|TsvSnapshot::from_sqlite_database_receiving(&database,control,owner)).unwrap_err();assert_eq!(error.kind.as_str(),refusal["kind"].as_str().unwrap());}let limits=semio_framework_os_kernel::sqlite_snapshot::SqliteDatabaseLimits{max_allocation_bytes:0,..Default::default()};assert_eq!(decode(&law,full,&mut |_|true,&mut |_|true,limits,|control,owner|source.to_sqlite_database_receiving(control,owner)).unwrap_err().kind,ValueRefusalKind::OwnershipLimit);assert_eq!(encode(&law,full,&mut |_|true,&mut |_|true,limits,|control,owner|TsvSnapshot::from_sqlite_database_receiving(&database,control,owner)).unwrap_err().kind,ValueRefusalKind::OwnershipLimit);eprintln!("[DEBUG] Original TSV receiving refuses each independent physical axis and zero SQL backing before birth with exact denied-close and funded terminal conservation");}
#[test]
fn sqlite_snapshot_tsv_receiving_original_every_sql_and_native_cancellation(){let law=policy();let source=wide(&law);let database=input(&source);let full=grant(&law["bodyGrant"]);let maximum=law["maximumCancellationCheckpoints"].as_u64().unwrap()as usize;let bytes=law["stringBytes"].as_u64().unwrap()as usize;
 for direction in [false,true]{let sql=Cell::new(0usize);let native=Cell::new(0usize);let prefix=Cell::new(false);let mut sql_callback=|event:semio_framework_os_kernel::sqlite_snapshot::SqliteSnapshotProgress|{sql.set(sql.get()+1);if event.total==bytes&&event.completed>0&&event.completed<bytes{prefix.set(true)}true};if direction{encode(&law,full,&mut sql_callback,&mut |_|{native.set(native.get()+1);true},Default::default(),|control,owner|TsvSnapshot::from_sqlite_database_receiving(&database,control,owner)).unwrap();}else{decode(&law,full,&mut sql_callback,&mut |_|{native.set(native.get()+1);true},Default::default(),|control,owner|source.to_sqlite_database_receiving(control,owner)).unwrap();}assert!(prefix.get());assert!(sql.get()<maximum&&native.get()<maximum);
  for stop in 1..=sql.get(){let calls=Cell::new(0usize);let mut callback=|_|{calls.set(calls.get()+1);calls.get()<stop};let error=if direction{encode(&law,full,&mut callback,&mut |_|true,Default::default(),|control,owner|TsvSnapshot::from_sqlite_database_receiving(&database,control,owner)).unwrap_err()}else{decode(&law,full,&mut callback,&mut |_|true,Default::default(),|control,owner|source.to_sqlite_database_receiving(control,owner)).unwrap_err()};assert_eq!(error.kind,ValueRefusalKind::Canceled);}
  for stop in 1..=native.get(){let calls=Cell::new(0usize);let mut callback=|_|{calls.set(calls.get()+1);calls.get()!=stop};let error=if direction{encode(&law,full,&mut |_|true,&mut callback,Default::default(),|control,owner|TsvSnapshot::from_sqlite_database_receiving(&database,control,owner)).unwrap_err()}else{decode(&law,full,&mut |_|true,&mut callback,Default::default(),|control,owner|source.to_sqlite_database_receiving(control,owner)).unwrap_err()};assert_eq!(error.kind,ValueRefusalKind::Canceled);}
  eprintln!("[DEBUG] Original TSV receiving directionReconstruct={direction} canceled every original SQL={} Native={} checkpoint, including98304-byte actual UTF8 prefixes and staged output transfer; exact allocation/release conservation reached funded terminal",sql.get(),native.get());
 }
}
#[test]
fn sqlite_snapshot_tsv_receiving_original_invalid_domain_and_exact_sql_literals(){let law=policy();let source=wide(&law);let full=grant(&law["bodyGrant"]);for edit in law["lateMutations"].as_array().unwrap(){let mut database=input(&source);let row=database.tables[2].rows.last_mut().unwrap();row.values[match edit["column"].as_str().unwrap(){"ordinal"=>2,"record_id"=>1,_=>unreachable!()}]=SqliteValue::Integer(edit["value"].as_i64().unwrap());let error=encode(&law,full,&mut |_|true,&mut |_|true,Default::default(),|control,owner|TsvSnapshot::from_sqlite_database_receiving(&database,control,owner)).unwrap_err();assert_eq!(error.kind.as_str(),edit["kind"].as_str().unwrap());if edit["column"]=="ordinal"{assert!(error.retained_progress().copied_bytes>=law["stringBytes"].as_u64().unwrap()as usize)}}for edit in law["documentMutations"].as_array().unwrap(){let mut database=input(&source);let cell=&mut database.tables[0].rows[0].values[if edit["column"]=="line_ending"{3}else{2}];*cell=match &edit["value"]{serde_json::Value::String(value)=>SqliteValue::Text(value.clone()),value=>SqliteValue::Integer(value.as_i64().unwrap())};assert_eq!(encode(&law,full,&mut |_|true,&mut |_|true,Default::default(),|control,owner|TsvSnapshot::from_sqlite_database_receiving(&database,control,owner)).unwrap_err().kind,ValueRefusalKind::InvalidValue);}for edit in law["sqlMutations"].as_array().unwrap(){let mut database=input(&source);database.tables[0].sql=database.tables[0].sql.replacen(edit["from"].as_str().unwrap(),edit["to"].as_str().unwrap(),1);assert_eq!(encode(&law,full,&mut |_|true,&mut |_|true,Default::default(),|control,owner|TsvSnapshot::from_sqlite_database_receiving(&database,control,owner)).unwrap_err().kind,ValueRefusalKind::InvalidValue);}eprintln!("[DEBUG] Original TSV receiving rejects malformed SQL token boundaries, changed quoted literal case, invalid newline metadata and dangling/late ordinal edits; copied first-field custody reaches exact funded terminal");}
#[test]
fn sqlite_snapshot_tsv_receiving_original_value_and_allocation_ceilings(){let law=policy();let source=wide(&law);let database=input(&source);let full=grant(&law["bodyGrant"]);let mut bytes=0usize;for table in &database.tables{for row in &table.rows{for value in &row.values{bytes+=match value{SqliteValue::Integer(_)|SqliteValue::Real(_)=>8,SqliteValue::Text(value)=>value.len(),SqliteValue::Blob(value)=>value.len(),SqliteValue::Null=>0};}}}let exact=semio_framework_os_kernel::sqlite_snapshot::SqliteDatabaseLimits{max_value_bytes:bytes,..Default::default()};decode(&law,full,&mut |_|true,&mut |_|true,exact,|control,owner|source.to_sqlite_database_receiving(control,owner)).unwrap();encode(&law,full,&mut |_|true,&mut |_|true,exact,|control,owner|TsvSnapshot::from_sqlite_database_receiving(&database,control,owner)).unwrap();let refused=semio_framework_os_kernel::sqlite_snapshot::SqliteDatabaseLimits{max_value_bytes:bytes-1,..Default::default()};assert_eq!(decode(&law,full,&mut |_|true,&mut |_|true,refused,|control,owner|source.to_sqlite_database_receiving(control,owner)).unwrap_err().kind,ValueRefusalKind::OwnershipLimit);assert_eq!(encode(&law,full,&mut |_|true,&mut |_|true,refused,|control,owner|TsvSnapshot::from_sqlite_database_receiving(&database,control,owner)).unwrap_err().kind,ValueRefusalKind::OwnershipLimit);eprintln!("[DEBUG] Original TSV receiving exact literal SQL value ceiling passes, one byte short refuses with cumulative original allocation/body receipts preserved");}
#[test]
fn sqlite_snapshot_tsv_receiving_original_cumulative_secondary_refusal(){let law=policy();let source=snapshot(&law["cases"][0]);let database=input(&source);let full=grant(&law["bodyGrant"]);let(projected,error)=decode(&law,full,&mut |_|true,&mut |_|true,Default::default(),|control,owner|{let output=source.to_sqlite_database_receiving(control,owner)?;let prior=owner.progress();let limits=control.limits();control.restrict_limits(semio_framework_os_kernel::sqlite_snapshot::SqliteDatabaseLimits{max_allocation_bytes:limits.max_allocation_bytes-control.allocation_remaining_bytes(),..limits})?;let error=source.to_sqlite_database_receiving(control,owner).unwrap_err();assert_eq!(owner.progress(),prior);assert_eq!(error.retained_progress(),prior);Ok((output,error))}).unwrap();assert_eq!(error.kind,ValueRefusalKind::OwnershipLimit);assert_eq!(projected.tables[1].rows,database.tables[1].rows);let(rebuilt,error)=encode(&law,full,&mut |_|true,&mut |_|true,Default::default(),|control,owner|{let output=TsvSnapshot::from_sqlite_database_receiving(&database,control,owner)?;let prior=owner.progress();let limits=control.limits();control.restrict_limits(semio_framework_os_kernel::sqlite_snapshot::SqliteDatabaseLimits{max_allocation_bytes:limits.max_allocation_bytes-control.allocation_remaining_bytes(),..limits})?;let error=TsvSnapshot::from_sqlite_database_receiving(&database,control,owner).unwrap_err();assert_eq!(owner.progress(),prior);assert_eq!(error.retained_progress(),prior);Ok((output,error))}).unwrap();assert_eq!(error.kind,ValueRefusalKind::OwnershipLimit);assert_eq!(rebuilt,source);eprintln!("[DEBUG] Original TSV receiving secondary zero-backing refusal preserves the already published producer output and cumulative original progress without aggregate/delta double admission");}
#[test]
fn sqlite_snapshot_tsv_receiving_original_exact_schema_metadata_ceiling(){let law=policy();let source=snapshot(&law["cases"][0]);let full=grant(&law["bodyGrant"]);let database=decode(&law,full,&mut |_|true,&mut |_|true,Default::default(),|control,owner|source.to_sqlite_database_receiving(control,owner)).unwrap();let bytes=database.tables.iter().map(|table|table.name.len()+table.sql.len()).sum::<usize>();let exact=semio_framework_os_kernel::sqlite_snapshot::SqliteDatabaseLimits{max_schema_bytes:bytes,..Default::default()};decode(&law,full,&mut |_|true,&mut |_|true,exact,|control,owner|source.to_sqlite_database_receiving(control,owner)).unwrap();assert_eq!(encode(&law,full,&mut |_|true,&mut |_|true,exact,|control,owner|TsvSnapshot::from_sqlite_database_receiving(&database,control,owner)).unwrap(),source);let refused=semio_framework_os_kernel::sqlite_snapshot::SqliteDatabaseLimits{max_schema_bytes:bytes-1,..Default::default()};assert_eq!(decode(&law,full,&mut |_|true,&mut |_|true,refused,|control,owner|source.to_sqlite_database_receiving(control,owner)).unwrap_err().kind,ValueRefusalKind::OwnershipLimit);assert_eq!(encode(&law,full,&mut |_|true,&mut |_|true,refused,|control,owner|TsvSnapshot::from_sqlite_database_receiving(&database,control,owner)).unwrap_err().kind,ValueRefusalKind::OwnershipLimit);eprintln!("[DEBUG] Original TSV receiving exact authored declaration plus table-name byte ceiling passes and one byte short refuses under original physical custody");}
